#!/usr/bin/env bash
# Writes web/config.js from deployments.env (public addresses only) and public RPC URLs.
set -euo pipefail; cd "$(dirname "$0")/.."
source deployments.env
cat > web/config.js <<EOF
// GENERATED by script/gen_web_config.sh. Public addresses and public RPC endpoints only.
export const CONFIG = {
  reactive: "$REACTIVE",
  chains: {
    lasna:    { name: "Reactive Lasna",   rpc: "https://lasna-rpc.rnk.dev/",       explorer: "https://lasna.reactscan.net/" },
    base:     { name: "Base Sepolia",     rpc: "https://sepolia.base.org",         explorer: "https://sepolia.basescan.org/",  pool: "$POOL_BASE" },
    unichain: { name: "Unichain Sepolia", rpc: "https://sepolia.unichain.org",     explorer: "https://sepolia.uniscan.xyz/",   pool: "$POOL_UNI" },
  },
  collateralOnlyPool: "$POOL_UNI_COLL",
};
EOF
echo "wrote web/config.js"
